@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{--ink:#172a2c;--muted:#75817b;--paper:#f4f3ed;--line:#e6e5dc;--green:#356e58;--green-bright:#6fc499;--orange:#db7655;--gold:#e4bd70;--navy:#13242a}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:Manrope, sans-serif;min-height:100vh}button{font:inherit}.game-shell{max-width:1512px;margin:0 auto;padding:0 56px}.topbar{height:78px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:11px;text-decoration:none;color:var(--ink);font-size:15px;font-weight:800;letter-spacing:.16em}.brand-mark{display:grid;place-items:center;background:var(--green);color:white;width:30px;height:30px;border-radius:9px;font-size:17px;letter-spacing:0;font-weight:800}.brand-dot{color:var(--orange)}.season,.map-coords,.eyebrow,.map-topline,.map-bottomline,.section-label,.resource-info span,.progress-meta,.progress-foot,.action-cost,.turn-footer,.site-footer{font-family:'DM Mono',monospace}.season{display:flex;align-items:center;gap:10px;font-size:10px;letter-spacing:.12em;color:#69756f}.season b{color:#c3c6b9}.live-dot{display:inline-block;width:7px;height:7px;background:#67b887;border-radius:50%;box-shadow:0 0 0 3px #67b88725}.icon-button{width:34px;height:34px;border:1px solid var(--line);background:transparent;border-radius:50%;color:#52635d;font-size:19px;cursor:pointer}.game-layout{display:grid;grid-template-columns:minmax(0,1fr) 330px;gap:34px;padding:31px 0 25px}.map-column{min-width:0}.map-heading{display:flex;align-items:end;justify-content:space-between;margin:0 0 18px}.eyebrow{font-size:9px;letter-spacing:.16em;color:#849087;margin:0 0 7px}.map-heading h1{margin:0;font-size:27px;letter-spacing:-.055em;font-weight:700}.map-coords{text-align:right;font-size:9px;line-height:1.75;color:#9aa198;letter-spacing:.11em}.map-coords span{color:#52615b}.map-frame{position:relative;overflow:hidden;background:#dce7d7;border-radius:13px;border:1px solid #d5dfd1;aspect-ratio:1.48;min-height:380px;box-shadow:0 13px 35px #405d4110;touch-action:pan-x pan-y}.map-frame canvas{display:block;width:100%;height:100%;cursor:crosshair;outline:none}.map-topline,.map-bottomline{position:absolute;left:15px;right:15px;display:flex;justify-content:space-between;align-items:center;pointer-events:none;color:#55725c;font-size:8px;letter-spacing:.11em}.map-topline{top:14px}.map-bottomline{bottom:13px;color:#59745d}.map-tag{background:#f4f5e8d9;border:1px solid #aebda344;border-radius:4px;padding:6px 8px;display:flex;align-items:center;gap:6px}.map-tag i{width:5px;height:5px;background:#53815d;border-radius:50%}.map-hint{background:#f5f5e9ba;border-radius:3px;padding:5px 7px}.toast{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%) translateY(8px);padding:11px 15px;border-radius:6px;background:#142b2ddd;color:white;font:10px 'DM Mono',monospace;letter-spacing:.06em;opacity:0;pointer-events:none;transition:opacity .2s,transform .2s;white-space:nowrap;z-index:4}.toast.show{opacity:1;transform:translate(-50%,-50%)}.legend{display:flex;align-items:center;gap:21px;padding:14px 2px;color:#758078;font-size:10px}.legend>span{display:flex;align-items:center;gap:7px}.legend-swatch{display:inline-block;width:9px;height:9px;border-radius:3px;background:#6c9e74}.legend-swatch.rival{background:#dc8065}.legend-swatch.wild{background:#c9d4bb}.legend-swatch.city{background:#e2b85f;border:2px solid #fff;width:10px;height:10px;box-shadow:0 0 0 1px #b28a38}.command-column{display:flex;flex-direction:column;gap:12px}.objective-card{background:var(--navy);color:#f4f5eb;border-radius:11px;padding:20px 21px 17px;position:relative;overflow:hidden}.objective-card:after{content:'';position:absolute;right:-60px;top:-85px;width:210px;height:210px;border:1px solid #ffffff0e;border-radius:50%;box-shadow:0 0 0 26px #ffffff08,0 0 0 52px #ffffff05;pointer-events:none}.objective-head{display:flex;align-items:center;justify-content:space-between}.objective-head .eyebrow{color:#9eaca1;margin:0}.target-chip{color:#b4dbbf;border:1px solid #b4dbbf44;background:#74ab7b1c;border-radius:20px;padding:5px 8px;font:10px 'DM Mono',monospace}.objective-title{font-size:29px;font-weight:700;line-height:1.07;letter-spacing:-.06em;margin-top:12px}.objective-title span{color:#7ac396}.objective-card>p{color:#a7b3a9;font-size:10px;line-height:1.65;margin:10px 0 19px;max-width:220px}.progress-meta,.progress-foot{display:flex;justify-content:space-between;align-items:center;font-size:8px;letter-spacing:.08em;color:#99aaa0}.progress-meta b{font:14px Manrope,sans-serif;color:#f1f3e7}.progress-track{height:6px;background:#f1f0e52b;border-radius:5px;margin:8px 0;position:relative}.progress-fill{width:12%;height:100%;border-radius:5px;background:#7fc594;transition:width .5s}.goal-marker{position:absolute;left:80%;top:-3px;height:12px;border-left:1px dashed #e6d188}.progress-foot{font-size:8px;color:#82948a}.resources-card,.action-card,.selection-card{background:#fffefa;border:1px solid #e8e7df;border-radius:9px;padding:13px 15px}.section-label{display:flex;justify-content:space-between;align-items:center;font-size:8px;letter-spacing:.12em;color:#829087}.income-label{color:#57936c;font-size:8px}.resource-row{display:flex;align-items:center;gap:9px;padding-top:13px}.resource-icon{width:27px;height:27px;border-radius:8px;display:grid;place-items:center;font-size:14px}.coin-icon{background:#f5edda;color:#ae8841}.troop-icon{background:#e8eeea;color:#507960}.nuke-icon{background:#f5e8e2;color:#ba7154}.resource-info{display:flex;flex-direction:column;gap:2px;min-width:28px}.resource-info b{font-size:15px;line-height:1}.resource-info span{font-size:7px;color:#939a8f;letter-spacing:.08em}.resource-divider{height:25px;border-left:1px solid #e9e9e0;margin:0 2px}.action-card{padding:14px 12px 9px}.action-card>.section-label{padding:0 3px 9px}.command-helper{color:#a4a99e;font-size:7px}.action-list{display:flex;flex-direction:column;gap:4px}.action-button{position:relative;display:flex;align-items:center;text-align:left;width:100%;border:1px solid transparent;background:transparent;border-radius:7px;padding:8px 7px;cursor:pointer;color:var(--ink);transition:background .15s,border-color .15s}.action-button:hover{background:#f5f6ef}.action-button.active{background:#eff4ed;border-color:#e0e9dd}.action-icon{flex:0 0 28px;width:28px;height:28px;border-radius:7px;display:grid;place-items:center;font-size:15px;margin-right:9px}.expand-icon{background:#e2eee3;color:#4b8560}.city-icon{background:#f2ecdc;color:#ad8c4c;font-size:18px}.attack-icon{background:#f6e8e2;color:#bd6d53}.nuke-action-icon{background:#ede9ec;color:#815d71}.action-copy{display:flex;flex-direction:column;gap:2px}.action-copy b{font-size:10px;font-weight:700}.action-copy small{font-size:8px;color:#92988f}.action-cost{margin-left:auto;font-size:8px;color:#777e73;white-space:nowrap}.nuke-action .action-cost{color:#aa6c59}.selection-card{display:flex;align-items:center;gap:10px;padding:11px 13px;min-height:58px}.selection-pin{width:26px;height:26px;border-radius:50%;display:grid;place-items:center;background:#edf2eb;color:#548061;font-size:17px}.selection-card>div:last-child{display:flex;flex-direction:column;gap:2px}.selection-card .eyebrow{font-size:7px;margin:0}.selection-card b{font-size:10px}.selection-card small{font-size:8px;color:#8c958c}.turn-footer{display:flex;align-items:center;justify-content:space-between;padding:1px 3px;color:#819087;font-size:8px;letter-spacing:.08em}.turn-footer>span{display:flex;align-items:center;gap:7px}.turn-footer .live-dot{width:6px;height:6px}.turn-footer button{border:0;background:transparent;color:#53675d;font:9px 'DM Mono',monospace;letter-spacing:.08em;cursor:pointer;padding:7px}.turn-footer button b{font-size:12px;margin-left:4px;color:#588666}.site-footer{border-top:1px solid var(--line);height:45px;display:flex;align-items:center;justify-content:space-between;color:#929991;font-size:8px;letter-spacing:.11em}.site-footer b{color:#d39b66}.modal-backdrop{position:fixed;inset:0;background:#102321b8;backdrop-filter:blur(5px);display:grid;place-items:center;z-index:10;padding:20px}.modal-backdrop.hidden{display:none}.result-modal{max-width:370px;width:100%;background:#fbfaf4;border-radius:14px;padding:36px 34px;text-align:center;box-shadow:0 24px 80px #06120d66}.result-emblem{display:grid;place-items:center;width:58px;height:58px;border-radius:18px;margin:0 auto 20px;background:#e7f0e5;color:#4d865f;font-size:26px}.result-modal .eyebrow{margin-bottom:9px}.result-modal h2{margin:0;font-size:29px;letter-spacing:-.06em}.result-modal>p:not(.eyebrow){color:#7e8980;font-size:12px;line-height:1.6;margin:11px auto 23px}.result-modal button{border:0;border-radius:7px;background:#356e58;color:white;padding:13px 18px;font:10px 'DM Mono',monospace;letter-spacing:.1em;cursor:pointer}.result-modal button span{margin-left:10px}
@media(max-width:1050px){.game-shell{padding:0 28px}.game-layout{grid-template-columns:minmax(0,1fr) 300px;gap:22px}.map-frame{min-height:350px}.action-button{padding:7px 5px}.action-copy b{font-size:9px}}
@media(max-width:760px){.game-shell{padding:0 15px}.topbar{height:60px}.season{font-size:8px;gap:7px}.brand{font-size:13px}.game-layout{grid-template-columns:1fr;gap:13px;padding:20px 0}.map-heading{margin-bottom:12px}.map-heading h1{font-size:23px}.map-frame{aspect-ratio:1.16;min-height:310px;max-height:430px}.legend{gap:12px;flex-wrap:wrap;font-size:9px;padding:10px 2px}.command-column{display:grid;grid-template-columns:1fr 1fr;align-items:start;gap:9px}.objective-card{grid-column:1/2;grid-row:1/2;padding:15px}.resources-card{grid-column:2/3;grid-row:1/2;padding:13px 10px}.objective-title{font-size:23px;margin-top:10px}.objective-card>p{font-size:9px;margin:8px 0 14px}.resource-row{gap:5px}.resource-icon{width:24px;height:24px}.resource-info b{font-size:13px}.resource-info span{font-size:6px}.resource-divider{margin:0}.action-card{grid-column:1/3;grid-row:2/3}.action-list{display:grid;grid-template-columns:1fr 1fr;gap:4px}.action-button{min-height:52px;padding:7px 5px}.action-icon{margin-right:6px;width:25px;height:25px;flex-basis:25px}.action-cost{font-size:7px}.selection-card{grid-column:1/2;grid-row:3/4}.turn-footer{grid-column:2/3;grid-row:3/4;align-self:center}.site-footer{height:38px;font-size:7px}}
@media(max-width:390px){.game-shell{padding:0 10px}.command-column{gap:7px}.objective-card{padding:12px}.resources-card{padding:12px 7px}.resource-row{gap:4px}.resource-divider{height:21px}.resource-icon{width:21px;height:21px}.resource-info b{font-size:12px}.action-copy small{font-size:7px}}

(() => {
  const SIZE = 9;
  const canvas = document.getElementById('gameCanvas');
  const ctx = canvas.getContext('2d');
  const frame = document.getElementById('mapFrame');
  const $ = (id) => document.getElementById(id);
  const palette = {
    neutral: {top:'#c6d6b7', left:'#a8b99e', right:'#b7c8aa', edge:'#8fa28d'},
    player: {top:'#75ad83', left:'#578b6c', right:'#659c75', edge:'#457b60'},
    enemy: {top:'#df9277', left:'#be705c', right:'#d07f66', edge:'#a85d4d'},
    water: {top:'#8cbbc0', left:'#6ca0a8', right:'#7eafb5', edge:'#588a93'}
  };
  const map = [];
  let coins = 48, army = 9, nukes = 1, day = 1, selected = null, action = 'expand';
  let gameOver = false, toastTimer, animation = 0, lastTick = Date.now(), soundOn = false;
  let flash = null;

  // A hand-shaped basin with two strongholds and a few impassable lakes.
  const water = new Set(['0,4','1,4','1,5','7,3','7,4','8,4']);
  const cities = new Set(['1,1','7,7']);
  for (let y=0;y<SIZE;y++) {
    const row=[];
    for (let x=0;x<SIZE;x++) {
      let owner = water.has(`${x},${y}`) ? 'water' : 'neutral';
      if ((x<=2 && y<=2) && owner!=='water') owner='player';
      if ((x>=6 && y>=6) && owner!=='water') owner='enemy';
      const city = cities.has(`${x},${y}`) && owner!=='water';
      row.push({x,y,owner,city,forest:((x*7+y*11+x*y)%5===0),radiation:0,seed:(x*43+y*17+13)%100});
    }
    map.push(row);
  }
  // Initial holdings are compact, with one city each and a neutral frontier.
  map[2][2].owner='neutral'; map[0][2].owner='neutral'; map[2][0].owner='neutral';
  map[1][1].owner='player'; map[7][7].owner='enemy';

  const allTiles=()=>map.flat();
  const tileAt=(x,y)=>map[y]?.[x]||null;
  const neighbors=(tile)=>[[tile.x-1,tile.y],[tile.x+1,tile.y],[tile.x,tile.y-1],[tile.x,tile.y+1]].map(([x,y])=>tileAt(x,y)).filter(Boolean);
  const owned=(who)=>allTiles().filter(t=>t.owner===who);
  const landCount=()=>allTiles().filter(t=>t.owner!=='water').length;
  const playerCount=()=>owned('player').length;
  const cityCount=()=>owned('player').filter(t=>t.city).length;
  const percent=()=>Math.floor(100*playerCount()/landCount());

  function resize() {
    const dpr=Math.min(window.devicePixelRatio||1,2);
    const width=Math.max(frame.clientWidth, window.innerWidth<=760 ? 450 : frame.clientWidth);
    const height=frame.clientHeight;
    canvas.style.width=`${width}px`; canvas.style.height=`${height}px`;
    canvas.width=Math.round(width*dpr); canvas.height=Math.round(height*dpr);
    ctx.setTransform(dpr,0,0,dpr,0,0);
    render();
  }
  function geometry() {
    const w=canvas.clientWidth,h=canvas.clientHeight;
    const tw=Math.min((w-32)/SIZE,(h-70)/(SIZE*.54));
    const th=tw*.54;
    return {w,h,tw,th,cx:w/2,top:(h-(SIZE-1)*th)/2-4};
  }
  function center(tile,g) { return {x:g.cx+(tile.x-tile.y)*g.tw/2,y:g.top+(tile.x+tile.y)*g.th/2}; }
  function diamond(x,y,tw,th) { ctx.beginPath();ctx.moveTo(x,y-th/2);ctx.lineTo(x+tw/2,y);ctx.lineTo(x,y+th/2);ctx.lineTo(x-tw/2,y);ctx.closePath(); }
  function color(hex,alpha) { return `${hex}${alpha}`; }

  function render() {
    if (!canvas.width) return;
    const g=geometry(); ctx.clearRect(0,0,g.w,g.h);
    const sky=ctx.createLinearGradient(0,0,0,g.h);sky.addColorStop(0,'#e3ebdb');sky.addColorStop(1,'#d7e3d4');ctx.fillStyle=sky;ctx.fillRect(0,0,g.w,g.h);
    // Quiet contour lines make the basin read as a raised 3D terrain map.
    ctx.save();ctx.globalAlpha=.22;ctx.strokeStyle='#a5bba4';ctx.lineWidth=1;
    for(let i=0;i<5;i++){ctx.beginPath();ctx.ellipse(g.cx,g.top+g.th*3.8,g.tw*(4.2+i*.38),g.th*(2.15+i*.22),-.08,0,Math.PI*2);ctx.stroke();}ctx.restore();
    const sorted=allTiles().sort((a,b)=>(a.x+a.y)-(b.x+b.y)||a.x-b.x);
    for(const t of sorted) drawTile(t,g);
    if(flash && Date.now()<flash.until){const p=center(flash.tile,g);ctx.save();ctx.globalAlpha=Math.max(0,(flash.until-Date.now())/850)*.5;ctx.fillStyle=flash.color;ctx.beginPath();ctx.arc(p.x,p.y,g.tw*.75,0,Math.PI*2);ctx.fill();ctx.restore();}
    animation++;
  }
  function drawTile(t,g) {
    const {x,y}=center(t,g),tw=g.tw,th=g.th,depth=Math.max(3,th*.17);
    const c=palette[t.owner];
    // Soft cast shadow, front and right beveled sides, then the top face.
    ctx.save();ctx.globalAlpha=.16;ctx.fillStyle='#324a3e';diamond(x+2,y+depth+2,tw,th);ctx.fill();ctx.restore();
    ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+tw/2,y-th/2);ctx.lineTo(x+tw/2,y-th/2+depth);ctx.lineTo(x,y+depth);ctx.closePath();ctx.fillStyle=c.right;ctx.fill();
    ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-tw/2,y-th/2);ctx.lineTo(x-tw/2,y-th/2+depth);ctx.lineTo(x,y+depth);ctx.closePath();ctx.fillStyle=c.left;ctx.fill();
    diamond(x,y,tw,th);ctx.fillStyle=c.top;ctx.fill();ctx.strokeStyle=color(c.edge,'55');ctx.lineWidth=1;ctx.stroke();
    if(t.owner==='water') {drawWater(t,x,y,g);return;}
    // Subtle terrain flecks vary tile-to-tile without visual clutter.
    ctx.save();diamond(x,y,tw,th);ctx.clip();ctx.globalAlpha=.22;ctx.fillStyle=t.owner==='enemy'?'#ffddbd':'#f1f3cc';
    for(let i=0;i<3;i++){let px=x+(((t.seed+i*31)%61)-30)*tw/90,py=y+(((t.seed+i*19)%23)-11)*th/34;ctx.beginPath();ctx.ellipse(px,py,tw*.035,th*.04,0,0,6.3);ctx.fill();}ctx.restore();
    if(t.owner==='neutral'&&t.forest) drawPines(x,y,g,t.seed);
    if(t.city) drawCity(x,y,g,t.owner);
    if(t.owner==='player'&&((t.x*3+t.y)%7===2)) drawUnit(x,y,g);
    if(t.radiation>0) drawRadiation(x,y,g);
    if(selected===t){ctx.save();diamond(x,y,tw*.99,th*.99);ctx.strokeStyle='#fff5bd';ctx.lineWidth=3;ctx.shadowColor='#fff';ctx.shadowBlur=8;ctx.stroke();ctx.restore();}
    if(action==='expand'&&selected&&selected.owner==='player'&&neighbors(selected).includes(t)&&t.owner==='neutral') drawMarker(x,y,g,'+');
    if(action==='attack'&&selected&&selected.owner==='player'&&neighbors(selected).includes(t)&&t.owner==='enemy') drawMarker(x,y,g,'!');
  }
  function drawWater(t,x,y,g){
    ctx.save();ctx.globalAlpha=.45;ctx.strokeStyle='#e2f0e8';ctx.lineWidth=1.5;
    for(let i=0;i<2;i++){ctx.beginPath();ctx.moveTo(x-g.tw*.13,y-g.th*.07+i*g.th*.13);ctx.quadraticCurveTo(x,y-g.th*.15+i*g.th*.13,x+g.tw*.14,y-g.th*.07+i*g.th*.13);ctx.stroke();}ctx.restore();
  }
  function drawPines(x,y,g,seed){
    const s=g.tw*.16, offsets=[[-.12,.02],[.08,-.08],[.18,.05]];
    offsets.forEach(([ox,oy],i)=>{const px=x+ox*g.tw,py=y+oy*g.th-(i===1?2:0);ctx.fillStyle='#66875f';ctx.fillRect(px-1,py,2,g.th*.12);ctx.beginPath();ctx.moveTo(px,py-s);ctx.lineTo(px-s*.66,py+s*.48);ctx.lineTo(px+s*.66,py+s*.48);ctx.closePath();ctx.fillStyle=(seed+i)%2?'#608568':'#6e966f';ctx.fill();ctx.beginPath();ctx.moveTo(px,py-s*.55);ctx.lineTo(px-s*.52,py+s*.65);ctx.lineTo(px+s*.52,py+s*.65);ctx.closePath();ctx.fillStyle='#7fa17a';ctx.fill();});
  }
  function drawCity(x,y,g,owner){
    const s=g.tw*.19, roof=owner==='enemy'?'#a95f50':'#a97b49';
    ctx.save();ctx.fillStyle='#40534a33';ctx.beginPath();ctx.ellipse(x,y+g.th*.1,s*1.35,s*.48,0,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#e9e4ce';ctx.fillRect(x-s*.72,y-s*.08,s*.62,s*.58);ctx.fillStyle='#d8d1b8';ctx.fillRect(x+s*.10,y-s*.02,s*.67,s*.52);
    ctx.fillStyle=roof;ctx.beginPath();ctx.moveTo(x-s*.78,y-s*.1);ctx.lineTo(x-s*.4,y-s*.49);ctx.lineTo(x-s*.02,y-s*.1);ctx.closePath();ctx.fill();ctx.beginPath();ctx.moveTo(x+s*.02,y-s*.03);ctx.lineTo(x+s*.43,y-s*.42);ctx.lineTo(x+s*.85,y-s*.03);ctx.closePath();ctx.fill();
    ctx.fillStyle='#b8c5a5';ctx.fillRect(x-s*.5,y+s*.12,s*.13,s*.17);ctx.fillRect(x+s*.3,y+s*.1,s*.14,s*.15);
    ctx.fillStyle=owner==='enemy'?'#e98b70':'#f2d07d';ctx.beginPath();ctx.arc(x,y-s*.61,s*.14,0,Math.PI*2);ctx.fill();ctx.restore();
  }
  function drawUnit(x,y,g){const s=g.tw*.09;ctx.save();ctx.fillStyle='#f8f2d9';ctx.strokeStyle='#568464';ctx.lineWidth=2;ctx.beginPath();ctx.arc(x+g.tw*.25,y-g.th*.1,s,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='#47755b';ctx.beginPath();ctx.arc(x+g.tw*.25,y-g.th*.1,s*.32,0,Math.PI*2);ctx.fill();ctx.restore();}
  function drawRadiation(x,y,g){ctx.save();ctx.globalAlpha=.35;ctx.fillStyle='#be9ba5';diamond(x,y,g.tw,g.th);ctx.fill();ctx.globalAlpha=.9;ctx.fillStyle='#754d64';ctx.font=`${g.tw*.2}px sans-serif`;ctx.textAlign='center';ctx.fillText('☢',x,y+g.th*.1);ctx.restore();}
  function drawMarker(x,y,g,symbol){ctx.save();ctx.fillStyle='#f8f2d8';ctx.strokeStyle=symbol==='!'?'#bc7058':'#508264';ctx.lineWidth=2;ctx.beginPath();ctx.arc(x,y,g.tw*.13,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle=symbol==='!'?'#bc7058':'#508264';ctx.font=`700 ${g.tw*.18}px Manrope`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(symbol,x,y);ctx.restore();}

  function hud(){
    const p=percent();$('percentLabel').textContent=`${p}%`;$('progressFill').style.width=`${Math.min(100,p)}%`;
    $('landCount').textContent=`${playerCount()} / ${landCount()} tiles`;$('coinCount').textContent=coins;$('armyCount').textContent=army;$('nukeCount').textContent=nukes;
    $('turnLabel').textContent=`DAY ${String(day).padStart(2,'0')}`;
    $('incomeLabel').textContent=`+${4+cityCount()*4} / DAY`;
    $('commandHelper').textContent=action==='expand'?'CLAIM THE FRONTIER':action==='city'?'SELECT YOUR LAND':action==='attack'?'CHOOSE A TARGET':'SELECT STRIKE ZONE';
    updateSelection();
    if(p>=80&&!gameOver) endGame(true);
    if(playerCount()===0&&!gameOver) endGame(false);
  }
  function updateSelection(){
    if(!selected){$('selectionTitle').textContent='No tile selected';$('selectionDetail').textContent='Choose a tile on the map to issue commands.';return;}
    const label=selected.owner==='player'?'Your territory':selected.owner==='enemy'?'Redhaven territory':selected.owner==='water'?'Lake':'Unclaimed land';
    $('selectionTitle').textContent=selected.city?`${label} · City`:label;
    $('selectionDetail').textContent=selected.owner==='player'?'Your border is ready for orders.':selected.owner==='enemy'?'Enemy defenses are active.':selected.owner==='water'?'Impassable water.':'Open frontier — claim it to expand.';
  }
  function notify(message){const el=$('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1900);}
  function setAction(next){action=next;document.querySelectorAll('.action-button').forEach(b=>b.classList.toggle('active',b.dataset.action===next));render();}
  function setSelected(t){selected=t;updateSelection();render();}
  function canReach(t,owner){return neighbors(t).some(n=>n.owner===owner);}
  function actExpand(target){
    if(target.owner!=='neutral'){notify('Choose unclaimed land on the frontier.');return false;}
    const source=selected&&selected.owner==='player'&&neighbors(selected).includes(target)?selected:owned('player').find(n=>neighbors(n).includes(target));
    if(!source){notify('Select a tile on your border first.');return false;}
    if(coins<12){notify('Not enough supply — wait for your next income.');return false;}
    coins-=12;target.owner='player';target.forest=false;army++;setSelected(target);flash={tile:target,color:'#d5f1a6',until:Date.now()+850};notify('Frontier claimed · +1 army');return true;
  }
  function actCity(target){
    if(target.owner!=='player'){notify('Cities can only be founded on your land.');return false;}
    if(target.city){notify('A city already stands here.');return false;}
    if(coins<35){notify('A city needs 35 supply.');return false;}
    coins-=35;target.city=true;setSelected(target);flash={tile:target,color:'#ffe6a4',until:Date.now()+850};notify('City founded · +4 supply every day');return true;
  }
  function actAttack(target){
    if(target.owner!=='enemy'){notify('Select an adjacent Redhaven tile.');return false;}
    const source=selected&&selected.owner==='player'&&neighbors(selected).includes(target)?selected:owned('player').find(n=>neighbors(n).includes(target));
    if(!source){notify('No friendly troops adjacent to that tile.');return false;}
    if(coins<8){notify('Not enough supply to launch an attack.');return false;}
    if(army<2){notify('You need at least 2 army to attack.');return false;}
    coins-=8;
    const committed=Math.min(4,army), defense=target.city?7:3;
    army=Math.max(0,army-(committed-1));
    if(committed+Math.floor(Math.random()*3)>=defense){target.owner='player';target.city=false;target.forest=false;setSelected(target);flash={tile:target,color:'#ffe29e',until:Date.now()+900};notify('Victory! Redhaven territory captured.');}
    else{setSelected(source);flash={tile:target,color:'#f4a08c',until:Date.now()+900};notify('Attack repelled · regroup and build your army.');}
    return true;
  }
  function actNuke(target){
    if(target.owner==='water'){notify('Warheads cannot target open water.');return false;}
    if(nukes<1){notify('No warheads available. Build cities to earn more.');return false;}
    nukes--;let struck=0;
    for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){
      const t=tileAt(target.x+dx,target.y+dy);if(!t||t.owner==='water')continue;
      if(t.owner==='enemy'){t.owner='neutral';t.city=false;struck++;}
      if(t===target){t.owner='player';t.city=false;t.forest=false;}
      if(t.owner==='player'&&t!==target&&t.city)t.city=false;
      t.radiation=2;
    }
    target.owner='player';setSelected(target);flash={tile:target,color:'#fff3ae',until:Date.now()+1000};notify(`Impact! ${struck} enemy tiles neutralized.`);return true;
  }

  function enemyTurn(){
    const foes=owned('enemy');
    if(!foes.length)return;
    // Redhaven grows steadily toward the basin, but leaves the player room to react.
    if(day%2===0){
      const frontier=foes.flatMap(t=>neighbors(t).filter(n=>n.owner==='neutral'));
      if(frontier.length){const target=frontier[Math.floor(Math.random()*frontier.length)];target.owner='enemy';target.forest=false;}
    }
    if(day%5===0){
      const targets=foes.flatMap(t=>neighbors(t).filter(n=>n.owner==='player'&&!n.city));
      if(targets.length&&Math.random()<.48){const target=targets[Math.floor(Math.random()*targets.length)];target.owner='enemy';target.forest=false;if(selected===target)selected=null;notify('Redhaven pushed your border back!');}
    }
  }
  function advanceDay(){
    if(gameOver)return;
    day++;coins+=4+cityCount()*4;army=Math.min(99,army+Math.max(1,cityCount()));
    allTiles().forEach(t=>{if(t.radiation>0)t.radiation--;});
    if(day%6===0&&cityCount()>0)nukes=Math.min(3,nukes+1);
    enemyTurn();hud();render();
  }
  function endGame(won){
    gameOver=true;clearInterval(clock);$('resultModal').classList.remove('hidden');
    $('resultEyebrow').textContent=won?'THE CONTINENT IS YOURS':'YOUR BANNER HAS FALLEN';
    $('resultTitle').textContent=won?'A new age begins.':'The frontier is lost.';
    $('resultMessage').textContent=won?`You united ${playerCount()} of ${landCount()} tiles beneath one banner.`:'Redhaven claimed your final territory. Gather your strength and try again.';
    $('resultEmblem').textContent=won?'✦':'↺';
  }
  function hitTest(event){
    const rect=canvas.getBoundingClientRect();const px=event.clientX-rect.left,py=event.clientY-rect.top,g=geometry();
    const dx=(px-g.cx)/(g.tw/2),dy=(py-g.top)/(g.th/2);
    const x=Math.round((dx+dy)/2),y=Math.round((dy-dx)/2);
    const t=tileAt(x,y);if(!t)return null;
    const p=center(t,g);if(Math.abs(px-p.x)/(g.tw/2)+Math.abs(py-p.y)/(g.th/2)>1.05)return null;
    return t;
  }
  canvas.addEventListener('pointerdown',(event)=>{
    const t=hitTest(event);if(!t)return;event.preventDefault();
    if(t.owner==='water'){setSelected(t);notify('Water blocks expansion.');return;}
    if(action==='nuke'){actNuke(t);hud();render();return;}
    if(action==='city'){
      if(t.owner==='player'){actCity(t);hud();render();}
      else{setSelected(t);notify('Select a tile inside your borders to found a city.');}return;
    }
    if(action==='attack'){
      if(t.owner==='player'){setSelected(t);notify('Select an adjacent enemy tile to attack.');}
      else if(t.owner==='enemy'){actAttack(t);hud();render();}
      else{setSelected(t);notify('Redhaven is shown in rust red.');}return;
    }
    if(t.owner==='player'){setSelected(t);notify('Border selected · choose an adjacent tile to expand.');}
    else{actExpand(t);hud();render();}
  });
  document.querySelectorAll('.action-button').forEach(button=>button.addEventListener('click',()=>setAction(button.dataset.action)));
  $('endTurnButton').addEventListener('click',()=>{advanceDay();lastTick=Date.now();});
  $('restartButton').addEventListener('click',()=>location.reload());
  $('soundButton').addEventListener('click',()=>{soundOn=!soundOn;$('soundButton').textContent=soundOn?'♫':'♪';notify(soundOn?'Sound enabled':'Sound muted');});
  window.addEventListener('resize',resize);
  const clock=setInterval(()=>{if(Date.now()-lastTick>=9500){advanceDay();lastTick=Date.now();}},1000);
  resize();hud();
})();

