(() => {
  const SIZE=9,canvas=document.getElementById('gameCanvas'),ctx=canvas.getContext('2d'),frame=document.getElementById('mapFrame');
  const $=id=>document.getElementById(id), palette={neutral:['#c6d6b7','#a8b99e','#b7c8aa','#8fa28d'],player:['#75ad83','#578b6c','#659c75','#457b60'],enemy:['#df9277','#be705c','#d07f66','#a85d4d'],water:['#8cbbc0','#6ca0a8','#7eafb5','#588a93']};
  const map=[],water=new Set(['0,4','1,4','1,5','7,3','7,4','8,4']),citySeeds=new Set(['1,1','7,7']);
  let coins=48,army=9,nukes=1,day=1,selected=null,action='expand',gameOver=false,toastTimer,flash=null,lastTick=Date.now();
  for(let y=0;y<SIZE;y++){const row=[];for(let x=0;x<SIZE;x++){let owner=water.has(`${x},${y}`)?'water':'neutral';if(x<=2&&y<=2&&owner!=='water')owner='player';if(x>=6&&y>=6&&owner!=='water')owner='enemy';row.push({x,y,owner,city:citySeeds.has(`${x},${y}`)&&owner!=='water',forest:(x*7+y*11+x*y)%5===0,radiation:0,seed:(x*43+y*17+13)%100});}map.push(row);}
  map[2][2].owner='neutral';map[0][2].owner='neutral';map[2][0].owner='neutral';
  const all=()=>map.flat(),at=(x,y)=>map[y]?.[x]||null,neighbors=t=>[[t.x-1,t.y],[t.x+1,t.y],[t.x,t.y-1],[t.x,t.y+1]].map(([x,y])=>at(x,y)).filter(Boolean),owned=who=>all().filter(t=>t.owner===who),landCount=()=>all().filter(t=>t.owner!=='water').length,playerCount=()=>owned('player').length,cityCount=()=>owned('player').filter(t=>t.city).length,percent=()=>Math.floor(100*playerCount()/landCount());
  function resize(){const dpr=Math.min(window.devicePixelRatio||1,2),w=Math.max(frame.clientWidth,window.innerWidth<=760?450:frame.clientWidth),h=frame.clientHeight;canvas.style.width=`${w}px`;canvas.style.height=`${h}px`;canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);render();}
  function geo(){const w=canvas.clientWidth,h=canvas.clientHeight,tw=Math.min((w-32)/SIZE,(h-70)/(SIZE*.54)),th=tw*.54;return{w,h,tw,th,cx:w/2,top:(h-(SIZE-1)*th)/2-4};}
  function center(t,g){return{x:g.cx+(t.x-t.y)*g.tw/2,y:g.top+(t.x+t.y)*g.th/2};}
  function diamond(x,y,tw,th){ctx.beginPath();ctx.moveTo(x,y-th/2);ctx.lineTo(x+tw/2,y);ctx.lineTo(x,y+th/2);ctx.lineTo(x-tw/2,y);ctx.closePath();}
  function render(){if(!canvas.width)return;const g=geo();ctx.clearRect(0,0,g.w,g.h);const sky=ctx.createLinearGradient(0,0,0,g.h);sky.addColorStop(0,'#e3ebdb');sky.addColorStop(1,'#d7e3d4');ctx.fillStyle=sky;ctx.fillRect(0,0,g.w,g.h);
    ctx.save();ctx.globalAlpha=.22;ctx.strokeStyle='#a5bba4';ctx.lineWidth=1;for(let i=0;i<5;i++){ctx.beginPath();ctx.ellipse(g.cx,g.top+g.th*3.8,g.tw*(4.2+i*.38),g.th*(2.15+i*.22),-.08,0,Math.PI*2);ctx.stroke();}ctx.restore();
    all().sort((a,b)=>(a.x+a.y)-(b.x+b.y)||a.x-b.x).forEach(t=>drawTile(t,g));
    if(flash&&Date.now()<flash.until){const p=center(flash.tile,g);ctx.save();ctx.globalAlpha=Math.max(0,(flash.until-Date.now())/850)*.5;ctx.fillStyle=flash.color;ctx.beginPath();ctx.arc(p.x,p.y,g.tw*.75,0,Math.PI*2);ctx.fill();ctx.restore();}
  }
  function drawTile(t,g){const{x,y}=center(t,g),tw=g.tw,th=g.th,depth=Math.max(3,th*.17),c=palette[t.owner];
    ctx.save();ctx.globalAlpha=.16;ctx.fillStyle='#324a3e';diamond(x+2,y+depth+2,tw,th);ctx.fill();ctx.restore();
    ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+tw/2,y-th/2);ctx.lineTo(x+tw/2,y-th/2+depth);ctx.lineTo(x,y+depth);ctx.closePath();ctx.fillStyle=c[2];ctx.fill();
    ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-tw/2,y-th/2);ctx.lineTo(x-tw/2,y-th/2+depth);ctx.lineTo(x,y+depth);ctx.closePath();ctx.fillStyle=c[1];ctx.fill();
    diamond(x,y,tw,th);ctx.fillStyle=c[0];ctx.fill();ctx.strokeStyle=c[3]+'55';ctx.lineWidth=1;ctx.stroke();
    if(t.owner==='water'){waterArt(x,y,g);return;}
    ctx.save();diamond(x,y,tw,th);ctx.clip();ctx.globalAlpha=.22;ctx.fillStyle=t.owner==='enemy'?'#ffddbd':'#f1f3cc';for(let i=0;i<3;i++){const px=x+(((t.seed+i*31)%61)-30)*tw/90,py=y+(((t.seed+i*19)%23)-11)*th/34;ctx.beginPath();ctx.ellipse(px,py,tw*.035,th*.04,0,0,6.3);ctx.fill();}ctx.restore();
    if(t.owner==='neutral'&&t.forest)pines(x,y,g,t.seed);if(t.city)cityArt(x,y,g,t.owner);if(t.owner==='player'&&(t.x*3+t.y)%7===2)unitArt(x,y,g);if(t.radiation>0)radiationArt(x,y,g);
    if(selected===t){ctx.save();diamond(x,y,tw*.99,th*.99);ctx.strokeStyle='#fff5bd';ctx.lineWidth=3;ctx.shadowColor='#fff';ctx.shadowBlur=8;ctx.stroke();ctx.restore();}
    if(action==='expand'&&selected?.owner==='player'&&neighbors(selected).includes(t)&&t.owner==='neutral')marker(x,y,g,'+');if(action==='attack'&&selected?.owner==='player'&&neighbors(selected).includes(t)&&t.owner==='enemy')marker(x,y,g,'!');
  }
  function waterArt(x,y,g){ctx.save();ctx.globalAlpha=.45;ctx.strokeStyle='#e2f0e8';ctx.lineWidth=1.5;for(let i=0;i<2;i++){ctx.beginPath();ctx.moveTo(x-g.tw*.13,y-g.th*.07+i*g.th*.13);ctx.quadraticCurveTo(x,y-g.th*.15+i*g.th*.13,x+g.tw*.14,y-g.th*.07+i*g.th*.13);ctx.stroke();}ctx.restore();}
  function pines(x,y,g,seed){const s=g.tw*.16;[[-.12,.02],[.08,-.08],[.18,.05]].forEach(([ox,oy],i)=>{const px=x+ox*g.tw,py=y+oy*g.th-(i===1?2:0);ctx.fillStyle='#66875f';ctx.fillRect(px-1,py,2,g.th*.12);ctx.beginPath();ctx.moveTo(px,py-s);ctx.lineTo(px-s*.66,py+s*.48);ctx.lineTo(px+s*.66,py+s*.48);ctx.closePath();ctx.fillStyle=(seed+i)%2?'#608568':'#6e966f';ctx.fill();ctx.beginPath();ctx.moveTo(px,py-s*.55);ctx.lineTo(px-s*.52,py+s*.65);ctx.lineTo(px+s*.52,py+s*.65);ctx.closePath();ctx.fillStyle='#7fa17a';ctx.fill();});}
  function cityArt(x,y,g,owner){const s=g.tw*.19,roof=owner==='enemy'?'#a95f50':'#a97b49';ctx.save();ctx.fillStyle='#40534a33';ctx.beginPath();ctx.ellipse(x,y+g.th*.1,s*1.35,s*.48,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#e9e4ce';ctx.fillRect(x-s*.72,y-s*.08,s*.62,s*.58);ctx.fillStyle='#d8d1b8';ctx.fillRect(x+s*.1,y-s*.02,s*.67,s*.52);ctx.fillStyle=roof;ctx.beginPath();ctx.moveTo(x-s*.78,y-s*.1);ctx.lineTo(x-s*.4,y-s*.49);ctx.lineTo(x-s*.02,y-s*.1);ctx.closePath();ctx.fill();ctx.beginPath();ctx.moveTo(x+s*.02,y-s*.03);ctx.lineTo(x+s*.43,y-s*.42);ctx.lineTo(x+s*.85,y-s*.03);ctx.closePath();ctx.fill();ctx.fillStyle='#b8c5a5';ctx.fillRect(x-s*.5,y+s*.12,s*.13,s*.17);ctx.fillRect(x+s*.3,y+s*.1,s*.14,s*.15);ctx.fillStyle=owner==='enemy'?'#e98b70':'#f2d07d';ctx.beginPath();ctx.arc(x,y-s*.61,s*.14,0,Math.PI*2);ctx.fill();ctx.restore();}
  function unitArt(x,y,g){const s=g.tw*.09;ctx.save();ctx.fillStyle='#f8f2d9';ctx.strokeStyle='#568464';ctx.lineWidth=2;ctx.beginPath();ctx.arc(x+g.tw*.25,y-g.th*.1,s,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='#47755b';ctx.beginPath();ctx.arc(x+g.tw*.25,y-g.th*.1,s*.32,0,Math.PI*2);ctx.fill();ctx.restore();}
  function radiationArt(x,y,g){ctx.save();ctx.globalAlpha=.35;ctx.fillStyle='#be9ba5';diamond(x,y,g.tw,g.th);ctx.fill();ctx.globalAlpha=.9;ctx.fillStyle='#754d64';ctx.font=`${g.tw*.2}px sans-serif`;ctx.textAlign='center';ctx.fillText('☢',x,y+g.th*.1);ctx.restore();}
  function marker(x,y,g,s){ctx.save();ctx.fillStyle='#f8f2d8';ctx.strokeStyle=s==='!'?'#bc7058':'#508264';ctx.lineWidth=2;ctx.beginPath();ctx.arc(x,y,g.tw*.13,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle=ctx.strokeStyle;ctx.font=`700 ${g.tw*.18}px Manrope`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(s,x,y);ctx.restore();}

