function marker(x,y,g,s){ctx.save();ctx.fillStyle='#f8f2d8';ctx.strokeStyle=s==='!'?'#bc7058':'#508264';ctx.lineWidth=2;ctx.beginPath();ctx.arc(x,y,g.tw*.13,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle=ctx.strokeStyle;ctx.font=`700 ${g.tw*.18}px Manrope`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(s,x,y);ctx.restore();}

function updateSelection(){if(!selected){$('selectionTitle').textContent='No tile selected';$('selectionDetail').textContent='Choose a tile on the map to issue commands.';return;}const label=selected.owner==='player'?'Your territory':selected.owner==='enemy'?'Redhaven territory':selected.owner==='water'?'Lake':'Unclaimed land';$('selectionTitle').textContent=selected.city?`${label} · City`:label;$('selectionDetail').textContent=selected.owner==='player'?'Your border is ready for orders.':selected.owner==='enemy'?'Enemy defenses are active.':selected.owner==='water'?'Impassable water.':'Open frontier — claim it to expand.';}
